    27	sub _register_psi_trigger {
    28	    my ($path, $kind, $stall_us, $window_us) = @_;
    29	    return if $stall_us <= 0;
    30	
    31	    sysopen my $fh, $path, O_RDWR | O_NONBLOCK
    32	        or fatal("failed to open PSI trigger path $path: $!");
    33	    my $flags = fcntl($fh, F_GETFD, 0);
    34	    defined $flags or fatal("failed to read PSI $kind trigger descriptor flags at $path: $!");
    35	    fcntl($fh, F_SETFD, $flags | FD_CLOEXEC)
    36	        or fatal("failed to set close-on-exec on PSI $kind trigger at $path: $!");
    37	    my $trigger = "$kind $stall_us $window_us\n";
    38	    if (!print {$fh} $trigger) {
    39	        my $error = $!;
    40	        close $fh;
    41	        fatal("failed to register PSI $kind trigger at $path: $error");
    42	    }
    43	    $fh->flush or fatal("failed to flush PSI $kind trigger at $path: $!");
    44	    return {
    45	        fh => $fh,
    46	        kind => $kind,
    47	        stall_us => $stall_us,
    48	        window_us => $window_us,
    49	    };
